CREATE TYPE "UserRole" AS ENUM ('OWNER','ADMIN','MANAGER','AGENT');
CREATE TYPE "ContactIdentifierType" AS ENUM ('ZALO_ID','PHONE','EMAIL','EXTERNAL_ID');
CREATE TYPE "IntegrationKind" AS ENUM ('ZALO_OA','OTHER');
CREATE TYPE "MessageDirection" AS ENUM ('INBOUND','OUTBOUND');
CREATE TYPE "MessageStatus" AS ENUM ('RECEIVED','QUEUED','SENT','DELIVERED','FAILED');
CREATE TABLE "Tenant" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Tenant_pkey" PRIMARY KEY ("id"));
CREATE TABLE "User" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"email" TEXT NOT NULL,"displayName" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "UserRole" NOT NULL DEFAULT 'AGENT',"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Contact" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"displayName" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Contact_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ContactIdentifier" ("id" TEXT NOT NULL,"contactId" TEXT NOT NULL,"type" "ContactIdentifierType" NOT NULL,"value" TEXT NOT NULL,"normalized" TEXT NOT NULL,"source" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ContactIdentifier_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Assignment" ("id" TEXT NOT NULL,"contactId" TEXT NOT NULL,"userId" TEXT NOT NULL,"label" TEXT NOT NULL,"assignedBy" TEXT,"reason" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endedAt" TIMESTAMP(3),CONSTRAINT "Assignment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Integration" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"kind" "IntegrationKind" NOT NULL,"displayName" TEXT NOT NULL,"externalId" TEXT NOT NULL,"encryptedAuth" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT false,"lastSyncedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Integration_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Conversation" ("id" TEXT NOT NULL,"contactId" TEXT NOT NULL,"integrationId" TEXT NOT NULL,"externalId" TEXT NOT NULL,"lastMessageAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Conversation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Message" ("id" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"externalId" TEXT,"direction" "MessageDirection" NOT NULL,"status" "MessageStatus" NOT NULL,"text" TEXT,"payload" JSONB,"sentAt" TIMESTAMP(3),"receivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Message_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuickReply" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"category" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdBy" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "QuickReply_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WebhookEvent" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"eventType" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'RECEIVED',"requestHash" TEXT NOT NULL,"response" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"processedAt" TIMESTAMP(3),CONSTRAINT "WebhookEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"actorId" TEXT,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_tenantId_email_key" ON "User"("tenantId","email"); CREATE INDEX "User_tenantId_role_isActive_idx" ON "User"("tenantId","role","isActive");
CREATE INDEX "Contact_tenantId_createdAt_idx" ON "Contact"("tenantId","createdAt"); CREATE UNIQUE INDEX "ContactIdentifier_contactId_type_normalized_key" ON "ContactIdentifier"("contactId","type","normalized"); CREATE INDEX "ContactIdentifier_type_normalized_idx" ON "ContactIdentifier"("type","normalized");
CREATE INDEX "Assignment_contactId_active_idx" ON "Assignment"("contactId","active"); CREATE INDEX "Assignment_userId_active_idx" ON "Assignment"("userId","active"); CREATE UNIQUE INDEX "Integration_tenantId_kind_externalId_key" ON "Integration"("tenantId","kind","externalId"); CREATE UNIQUE INDEX "Conversation_integrationId_externalId_key" ON "Conversation"("integrationId","externalId"); CREATE INDEX "Conversation_contactId_lastMessageAt_idx" ON "Conversation"("contactId","lastMessageAt"); CREATE UNIQUE INDEX "Message_conversationId_externalId_key" ON "Message"("conversationId","externalId"); CREATE INDEX "Message_conversationId_createdAt_idx" ON "Message"("conversationId","createdAt"); CREATE INDEX "QuickReply_tenantId_isActive_category_idx" ON "QuickReply"("tenantId","isActive","category"); CREATE UNIQUE INDEX "WebhookEvent_tenantId_idempotencyKey_key" ON "WebhookEvent"("tenantId","idempotencyKey"); CREATE INDEX "WebhookEvent_tenantId_createdAt_idx" ON "WebhookEvent"("tenantId","createdAt"); CREATE INDEX "AuditLog_tenantId_createdAt_idx" ON "AuditLog"("tenantId","createdAt");
ALTER TABLE "User" ADD CONSTRAINT "User_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Contact" ADD CONSTRAINT "Contact_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ContactIdentifier" ADD CONSTRAINT "ContactIdentifier_contactId_fkey" FOREIGN KEY ("contactId") REFERENCES "Contact"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Assignment" ADD CONSTRAINT "Assignment_contactId_fkey" FOREIGN KEY ("contactId") REFERENCES "Contact"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Assignment" ADD CONSTRAINT "Assignment_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Integration" ADD CONSTRAINT "Integration_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Conversation" ADD CONSTRAINT "Conversation_contactId_fkey" FOREIGN KEY ("contactId") REFERENCES "Contact"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Message" ADD CONSTRAINT "Message_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "QuickReply" ADD CONSTRAINT "QuickReply_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WebhookEvent" ADD CONSTRAINT "WebhookEvent_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE ON UPDATE CASCADE;
